"""Pre-result binary32 velocity-to-force measurement resolution controls."""
from pathlib import Path
import json,hashlib,numpy as np
r=Path(__file__).resolve().parents[2];out=r/'runs/offline/moving_contact_precision_plan_20261102_01';out.mkdir(exist_ok=False);mass=.25;cases=[]
for dt in [1/9600,1/19200,1/38400]:
 v0=np.linspace(-.002001,-.001999,10001);F=np.linspace(-.002,.002,len(v0));v1=v0+dt*F/mass;a=v0.astype(np.float32);b=v1.astype(np.float32);res=mass*((b.astype(float)-a.astype(float))/dt)-F;floor=mass*(.5*abs(np.spacing(a)).astype(float)+.5*abs(np.spacing(b)).astype(float))/dt
 assert np.all(abs(res)<=floor+1e-14)
 cases.append(dict(dt_s=dt,analytic_cases=len(v0),maximum_binary32_momentum_rate_error_n=float(abs(res).max()),maximum_component_rounding_bound_n=float(floor.max()),original_one_micronewton_gate_failures=int(np.count_nonzero(abs(res)>1e-6))))
plan=dict(registered_before_any_moving_native_result=True,basis='Analytic propagation of half-ULP uncertainty from TWO binary32 endpoint velocity measurements into mass*(v1-v0)/dt. Coasting initial speed2mm/s gives a different measurement resolution from the zero-velocity preload. This is an additional measurement-reference version, not a material/contact/force-path modification.',original_absolute_force_gate_n=1e-6,original_absolute_moment_gate_nm=1e-7,additional_velocity_rounding_bound='Per Cartesian component b_i=m*(0.5*abs(spacing(float32(v0_i)))+0.5*abs(spacing(float32(v1_i))))/robot_dt. Compare norm(momentum-rate residual) <=1e-6+norm(b). No fitted correction, offset subtraction, sign adjustment or observed force scale enters b.',maximum_admissible_added_velocity_rounding_bound_n=3e-6,moment_gate='Original1e-7Nm retained without added allowance.',reporting='Always retain original raw1e-6 force pass/fail separately. A new quantization-aware measurement pass must be explicitly labelled with its actual resolution; it cannot relabel an old failure or claim the original1micronewton moving-velocity accuracy.',scope='Measured instantaneous knife Newton-Euler force derivative at the three declared moving coupling clocks only. Integrated target/robot impulse, float32 applied wrench, force arithmetic, CAD action/reaction, kinetic/work budgets and all physical stops remain unchanged.',analytic_controls=cases,source_sha256={str(Path(__file__).resolve()):hashlib.sha256(Path(__file__).read_bytes()).hexdigest()},experimental_validation='pending')
(out/'plan.json').write_text(json.dumps(plan,indent=2)+'\n');print(json.dumps(cases,indent=2))
